/**
 * Plain-language translations for everything written in `backend/app/data/schemes.json`.
 *
 * Why this is a separate file from backendStrings.js
 * -------------------------------------------------
 * backendStrings.js holds the sentences the Python *services compose* -- advice,
 * observations, risk reasons, summary lines. Those are generated per run and
 * change when a service changes. What is here instead is the prose that sits in
 * the scheme *dataset*: a scheme's description, what it gives you, who can
 * apply, and which papers to carry. Thirty schemes across seven layers of
 * government is roughly a thousand lines on its own, and mixing it into
 * backendStrings.js would have buried the service prose inside it.
 *
 * The split line, for anything added later: if a Python function builds the
 * sentence, it belongs in backendStrings.js. If the sentence is typed into
 * schemes.json, it belongs here.
 *
 * How a key gets here
 * -------------------
 * Every scheme in schemes.json carries a code beside each sentence --
 * `description_code`, `support_type_code`, and the `eligibility_codes` /
 * `document_codes` arrays, which are index-aligned with `eligibility_rules` /
 * `documents`. The frontend looks the code up here. The arrays are generated by
 * `backend/gen_schemes.py` so they cannot fall out of step, and
 * `test_every_scheme_carries_complete_translation_codes` checks the pairing over
 * the whole file rather than over one match list.
 *
 * Two rules that are easy to break
 * --------------------------------
 * 1. `tBackend()` never prints a dotted code. A missing key falls back to the
 *    English sentence the backend already sent, not to `sdata.kcc.description`.
 *    That is the opposite of `t()`, where a leaked key name is the point.
 * 2. The English here is a *plain-language rewrite*, not the schemes.json text.
 *    The dataset keeps the formal wording that a government portal uses, because
 *    that is what the API returns to any other consumer. What the reader sees is
 *    this: everyday words, addressed as "you". "Money you do not pay back",
 *    never "capital subsidy".
 *
 * Amounts stay in Latin digits and keep the `Rs.` / lakh / crore form that is
 * printed on Indian forms, in every language. Terminal punctuation follows the
 * script: `।` for Devanagari and Bengali, `.` for the Dravidian scripts.
 *
 * Scheme *names* are deliberately not translated anywhere -- the name on the
 * official portal is what an official will recognise.
 */

