  'doc.address': 'நீங்கள் எங்கு வசிக்கிறீர்கள் என்பதற்கான ஆவணம்',
  'doc.aadhaar': 'ஆதார் அட்டை',
  'doc.photo': 'சமீபத்திய பாஸ்போர்ட் அளவு புகைப்படம்',
