  'doc.businessDetails': 'உங்கள் தொழில் அல்லது திட்டத்தின் விவரம்',
  'doc.businessInfo': 'உங்கள் தொழில் அல்லது திட்டம் பற்றிய தகவல்',
  'doc.projectReport': 'தொழிலுக்கான எழுதப்பட்ட திட்டம்',
