  'sdata.svanidhi.description': 'நகரத்திலோ பட்டணத்திலோ தெருவில் விற்பவர்களுக்கு. நகர அலுவலகத்தின் விற்பனைச் சான்றிதழ் அல்லது கணக்கெடுப்புக் கடிதம் இருந்தால் Rs.10,000, பிறகு Rs.20,000, பிறகு Rs.50,000 என நடைமுறைக் கடன் கிடைக்கும்; சரியான நேரத்தில் செலுத்தினால் பணமும் திரும்பும்.',
