  'elig.pmfme.upgrade': 'একটি ইউনিট সম্পর্কে খাদ্য প্রক্রিয়াকরণ শিল্প মন্ত্রকের দেওয়া তথ্যে এই সরকারি টাকা সেই ইউনিটগুলোর জন্য বলা হয়েছে যারা নিজেদের ইউনিট আরও ভালো করতে চায়। নতুন ইউনিট এটা পেতে পারে কি না, তা সেখানে বলা নেই, তাই আবেদনের আগে আপনার ব্যাঙ্ক শাখায় জিজ্ঞেস করুন।',

