  'elig.pmegp.financing': 'ব্যাঙ্ক কত ঋণ দেবে আর আপনি কত দেবেন, তা PMEGP নিয়ম অনুযায়ী ঠিক হয়।',
  'elig.pmegp.period': '2022 সালের PMEGP নিয়মে এই প্রকল্প 2021-22 থেকে 2025-26 পর্যন্ত বছরগুলোর জন্য মঞ্জুর করা হয়েছে। 31 মার্চ 2026-এর পরেও এটা চলছে কি না, তা আমরা নিশ্চিত করিনি, তাই আবেদনের আগে আপনার জেলা শিল্প কেন্দ্রে জিজ্ঞেস করুন।',

